const domainIcons={ai:'cpu',robots:'bot',health:'stethoscope',energy:'leaf',security:'shield-check',creative:'palette',business:'chart-no-axes-combined',education:'book-open',city:'building-2',food:'wheat'};
function appIcon(name){return `<span class="app-icon" style="--glyph:url(icons/${name}.svg)" aria-hidden="true"></span>`}
titles.home=['MY FUTURE COMPASS','나의 미래 탐험','궁금한 미래를 알아보고, 나에게 맞는 공부와 직업을 찾아보세요.'];
function homePage(){const count=chosenSubjects.size+chosenActivities.size;const news=typeof newsData!=='undefined'&&newsData?.articles?.slice(0,3)||[];return `<div class="start-grid"><button class="start-card violet" data-start-route="flow"><span class="start-icon">${appIcon('sparkles')}</span><span class="start-text"><span class="start-label">미래에서 출발</span><strong>세상은 어떻게 바뀔까?</strong><span>10개 분야의 변화와 연결되는 직업 알아보기</span></span><span class="start-cta">미래 분야 탐색</span></button><button class="start-card teal" data-start-route="self"><span class="start-icon">${appIcon('compass')}</span><span class="start-text"><span class="start-label">나에게서 출발</span><strong>나는 무엇이 재미있을까?</strong><span>좋아하는 과목과 활동으로 관심 분야 찾기</span></span><span class="start-cta">나의 관심 선택</span></button></div><div class="journey-strip"><div><span class="journey-icon purple">${appIcon('heart')}</span><span><strong>${count?count+'개 관심 선택':'아직 모르면 괜찮아요'}</strong><small>${count?'관심 선택을 이어서 바꿀 수 있어요.':'과목보다 해보고 싶은 활동부터 골라도 돼요.'}</small></span></div><button data-page="plan"><span class="journey-icon orange">${appIcon('circle-check')}</span><span><strong>준비계획 ${completed.size} / 6단계</strong><small>주 2시간, 작은 경험부터 시작</small></span><span class="mini">이어보기</span></button></div><section class="section"><div class="section-heading"><div><span class="section-kicker">FUTURE WORLDS</span><h2>어떤 미래가 궁금해?</h2></div><button class="text-button" data-page="future">10·20·30년 뒤 보기</button></div><div class="world-grid">${domains.map(d=>`<button class="world-card" data-home-domain="${d.id}" data-field="${d.id}"><span class="domain-icon">${appIcon(domainIcons[d.id])}</span><strong>${d.name}</strong><span>${d.subjects.slice(0,3).join(' · ')}</span></button>`).join('')}</div></section><section class="section"><div class="section-heading"><div><span class="section-kicker">DAILY SIGNALS</span><h2>오늘의 AI 소식</h2></div><button class="text-button" data-page="news">전체 소식 보기</button></div><div class="home-news">${news.length?news.map(a=>`<a class="home-news-row" href="${escapeHTML(safeArticleURL(a.url))}" target="_blank" rel="noopener noreferrer"><span class="news-symbol">${appIcon('newspaper')}</span><span><small>${escapeHTML(a.source)} · ${dateLabel(a.published_at)}</small><strong>${escapeHTML(a.title)}</strong></span><span class="tag">${escapeHTML(a.category)}</span></a>`).join(''):'<div class="empty">공식 소식을 불러오는 중이에요. <button class="text-button" data-page="news">뉴스 화면에서 확인</button></div>'}</div><p class="mini">공식 발표의 원문 제목입니다. 발표 날짜와 실제 보급 시점은 다를 수 있어요.</p></section><section class="section"><div class="extra-grid">${[['life','heart','달라지는 생활','공부·집·이동은 어떻게 달라질까?'],['career','graduation-cap','직업과 대학','실제 업무, 관련 학과와 준비 공부'],['research','flask-conical','전망과 근거','확인된 연구와 미래 시나리오 구분']].map(([p,i,t,d])=>`<button class="extra-card" data-page="${p}">${appIcon(i)}<strong>${t}</strong><span>${d}</span></button>`).join('')}</div></section><p class="mini local-note">관심과 체크는 이 브라우저에만 저장돼요. 다른 기기와 자동 동기화되지는 않습니다.</p>`}
let installPrompt=null;
function announce(message){const el=document.querySelector('#app-message');if(!el)return;el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4500)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.startRoute){page='explore';route=b.dataset.startRoute;activeDomain=null;render();saveProgress();window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.homeDomain){page='career';activeDomain=b.dataset.homeDomain;render();document.querySelector('#domain-detail')?.scrollIntoView({behavior:'smooth',block:'start'})}if(b.hasAttribute('data-install')){if(installPrompt){await installPrompt.prompt();installPrompt=null}else document.querySelector('#install-dialog').showModal()}if(b.hasAttribute('data-close-install'))document.querySelector('#install-dialog').close();if(b.dataset.page)document.querySelector('.bottom-nav [aria-current="page"]')?.scrollIntoView({block:'nearest',inline:'nearest'})});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('appinstalled',()=>{installPrompt=null;announce('홈 화면에 추가했어요. 아이콘으로 다시 만나세요!')});
function connectionStatus(){const e=document.querySelector('#connection-status');if(e)e.textContent=typeof navigator!=='undefined'&&navigator.onLine===false?'오프라인 · 저장된 탐색':'나의 탐험 공간'}
window.addEventListener('online',()=>{connectionStatus();if(typeof refreshNews==='function')refreshNews()});window.addEventListener('offline',connectionStatus);
if(typeof navigator!=='undefined'&&'serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)announce('새 버전이 준비됐어요. 앱을 다시 열면 적용돼요.')})})}).catch(()=>{});}
page='home';
